 metinler=[
  M('Kur’an, Bakara 2/62', 'Kur’an’ın Yahudiler, Hristiyanlar ve Sâbiîleri birlikte andığı âyet; milel-nihal yazarlarının ve müfessirlerin Sâbiîler tartışmasının çıkış noktası.',
    'إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالنَّصَارَى وَالصَّابِئِينَ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'البقرة ٢/٦٢'),
  M('Kur’an, Hac 22/17', 'Kur’an’da altı din grubunun birlikte sayıldığı âyet; Âmirî gibi âlimler karşılaştırmalarını bu tasnife dayandırmıştır.',
    'إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالصَّابِئِينَ وَالنَّصَارَى وَالْمَجُوسَ وَالَّذِينَ أَشْرَكُوا إِنَّ اللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ شَهِيدٌ', 'الحج ٢٢/١٧'),
  M('Kur’an, Âl-i İmrân 3/64', 'Ehl-i kitaba ortak bir kelimeye davet; Müslüman-Hristiyan ilişkilerinde sık başvurulan âyet.',
    'قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ', 'آل عمران ٣/٦٤'),
  M('Kur’an, Mâide 5/48', 'Her ümmete ayrı bir şeriat ve yol verildiğini bildiren âyet parçası; şeriatlar arası farklılık ve nesih tartışmalarının dayanağı.',
    'لِكُلٍّ جَعَلْنَا مِنْكُمْ شِرْعَةً وَمِنْهَاجًا', 'المائدة ٥/٤٨'),
  M('Kur’an, Nahl 16/36', 'Her ümmete bir peygamber gönderildiğini bildiren âyet parçası; âlimlerin Hint ve İran dinlerinin kökeni hakkındaki tartışmalarında başvurulmuştur.',
    'وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ', 'النحل ١٦/٣٦'),
  M('Kur’an, Bakara 2/256', 'Dinde zorlama olmadığını bildiren âyet parçası; gayrimüslimlerle ilişkiler ve din özgürlüğü tartışmalarının temel naslarından.',
    'لَا إِكْرَاهَ فِي الدِّينِ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ', 'البقرة ٢/٢٥٦'),
  M('Hadis: Peygamberlerin dini birdir', 'Peygamberlerin dininin bir, şeriatlarının farklı olduğunu baba bir kardeşler benzetmesiyle anlatan hadis.',
    'الأَنْبِيَاءُ إِخْوَةٌ لِعَلَّاتٍ، أُمَّهَاتُهُمْ شَتَّى وَدِينُهُمْ وَاحِدٌ', 'البخاري، أحاديث الأنبياء ٤٨'),
  M('Hadis: Fıtrat', 'Her çocuğun fıtrat üzere doğduğunu, dinî kimliğin aile ve çevreyle şekillendiğini bildiren hadis; din psikolojisi ve dinin kökeni tartışmalarında Müslüman yazarlarca anılır.',
    'كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ، فَأَبَوَاهُ يُهَوِّدَانِهِ أَوْ يُنَصِّرَانِهِ أَوْ يُمَجِّسَانِهِ', 'البخاري، الجنائز ٩٢'),
  M('Bîrûnî, Tahkīku mâ li’l-Hind — mukaddime', 'Bîrûnî’nin kitabının bir münazara değil, Hintlilerin sözünü olduğu gibi aktaran bir anlatım kitabı olduğunu belirttiği yöntem cümlesi.',
    'وإنما هو كتاب حكاية، فأورد كلام الهند على وجهه، وأضيف إليه ما لليونانيين من مثله لتعريف المقاربة بينهم', 'تحقيق ما للهند، المقدمة'),
  M('Şehristânî, el-Milel ve’n-nihal — mukaddime', 'Şehristânî’nin her fırkanın görüşünü kendi kitaplarından ve taraf tutmadan aktarma şartı.',
    'وشرطي على نفسي أن أورد مذهب كل فرقة على ما وجدته في كتبهم، من غير تعصب لهم، ولا كسر عليهم', 'الملل والنحل، المقدمة الخامسة'),
 ],
